import './multiplayer.css'
import * as backend from './backend.js'

const $=id=>document.getElementById(id)
const LADDER=[1000,5000,10000,25000,50000,100000,250000,500000,1000000,2500000,5000000,10000000,25000000,50000000,100000000,150000000,250000000,400000000,700000000,1000000000]
const state={matchId:null,roomCode:'',isHost:false,ready:false,phase:'menu',round:0,timeLeft:30,answered:false,poll:null,timer:null,lastState:null}
const money=n=>`₦${Number(n||0).toLocaleString('en-NG')}`
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))
function notice(msg,type=''){const n=$('notice');n.textContent=msg;n.className='notice show '+type;setTimeout(()=>n.className='notice',2600)}
function renderShell(){document.body.innerHTML=`<main class="mp-shell"><header class="mp-header"><a href="/" class="mp-brand">♛ <b>BILLION</b><strong>RUSH</strong></a><div><span id="connection" class="pill">● OFFLINE</span><a class="back-link" href="/">HOME</a></div></header><section id="menu" class="mp-panel"><div class="eyebrow">HEAD-TO-HEAD • 2 PLAYERS</div><h1>RUSH <span>TOGETHER.</span></h1><p>Challenge another player in the same 20-question climb. Each round lasts 30 seconds. No paid entry. No wagering.</p><div class="mp-actions"><button id="quickMatch" class="mp-primary">QUICK MATCH <b>⚡</b></button><button id="createRoom" class="mp-secondary">CREATE PRIVATE ROOM</button><button id="joinRoom" class="mp-secondary">JOIN WITH CODE</button></div><div id="roomTools" class="room-tools hidden"><div><small>YOUR ROOM CODE</small><strong id="roomCode">------</strong></div><button id="copyCode">COPY CODE</button></div><div id="mpStatus" class="mp-status">Sign in to play multiplayer.</div></section><section id="lobby" class="mp-panel hidden"><div class="eyebrow">MATCH ROOM</div><div class="lobby-head"><div><h2>ROOM <span id="lobbyCode">------</span></h2><p id="lobbyStatus">Waiting for another player.</p></div><button id="leaveLobby" class="icon-btn">×</button></div><div class="players"><article><div class="avatar">YOU</div><b id="youName">You</b><span id="youReady">NOT READY</span></article><div class="vs">VS</div><article><div class="avatar">?</div><b id="opponentName">Waiting…</b><span id="opponentReady">Waiting for opponent</span></article></div><div class="lobby-actions"><button id="readyBtn" class="mp-primary">READY UP</button><button id="startMatchBtn" class="mp-secondary hidden">START MATCH</button></div></section><section id="game" class="mp-panel hidden"><div class="game-head"><div><small>QUESTION</small><strong id="round">01 / 20</strong></div><div class="mp-timer" id="timer">30</div><div><small>YOUR SCORE</small><strong id="score">₦0</strong></div></div><div class="opponent-strip"><span>OPPONENT</span><b id="opponentScore">₦0</b><em id="opponentState">Thinking…</em></div><div class="mp-question"><span id="difficulty">MEDIUM</span><h2 id="questionText">Loading…</h2><div id="options" class="options"></div><div id="reveal" class="reveal hidden"></div></div></section><section id="result" class="mp-panel hidden"><div class="eyebrow">MATCH COMPLETE</div><h1 id="resultTitle">RESULTS</h1><div class="result-grid"><div><small>YOUR SCORE</small><strong id="finalScore">₦0</strong></div><div><small>OPPONENT</small><strong id="finalOpponent">₦0</strong></div></div><p id="resultMessage"></p><div class="mp-actions"><button id="rematch" class="mp-primary">REMATCH</button><a href="/" class="mp-secondary">BACK HOME</a></div></section><div id="notice" class="notice"></div></main>`;bind();setConnection(true)}
function setConnection(on){const c=$('connection');c.textContent=on?'● CONNECTED':'● OFFLINE';c.className='pill '+(on?'online':'')}
function show(id,on){$(id)?.classList.toggle('hidden',!on)}
function requireAuth(){if(!backend.isConfigured()){notice('Backend is not configured. Create .env.local from .env.example and restart Vite.','error');return false}return true}
async function ensureAuth(){if(!requireAuth())return false;const s=await backend.getSession();if(!s){location.href='/login.html?next=/multiplayer.html';return false}return true}
async function createRoom(){if(!(await ensureAuth()))return;try{const r=await backend.createMatchRoom();enterLobby(r)}catch(e){notice(e.message||'Could not create room.','error')}}
async function joinRoom(){if(!(await ensureAuth()))return;const code=prompt('Enter the 6-character room code');if(!code)return;try{const r=await backend.joinMatchRoom(code);enterLobby(r)}catch(e){notice(e.message||'Could not join room.','error')}}
async function quickMatch(){if(!(await ensureAuth()))return;show('menu',false);show('lobby',true);$('lobbyStatus').textContent='Finding an opponent…';try{const r=await backend.findMatch();enterLobby(r)}catch(e){show('menu',true);show('lobby',false);notice(e.message||'Matchmaking failed.','error')}}
function enterLobby(r){state.matchId=r.matchId;state.roomCode=r.roomCode;state.isHost=!!r.isHost;state.ready=false;state.phase='lobby';$('roomCode').textContent=r.roomCode;$('lobbyCode').textContent=r.roomCode;$('roomTools').classList.remove('hidden');$('mpStatus').textContent=state.isHost?'Room created. Share the code with your opponent.':'You joined the room.';show('menu',false);show('lobby',true);$('startMatchBtn').classList.toggle('hidden',!state.isHost);pollState()}
async function setReady(){try{state.ready=!state.ready;await backend.setMatchReady(state.matchId,state.ready);$('readyBtn').textContent=state.ready?'NOT READY':'READY UP';$('youReady').textContent=state.ready?'READY':'NOT READY';pollState()}catch(e){state.ready=!state.ready;notice(e.message||'Could not change ready state.','error')}}
async function startMatch(){try{await backend.createMatch(state.matchId);await pollState()}catch(e){notice(e.message||'Both players must be ready.','error')}}
async function pollState(){if(!state.matchId)return;try{const s=await backend.getMatchState(state.matchId);state.lastState=s;setConnection(true);if(s.match.status==='waiting'){show('menu',false);show('lobby',true);const members=s.members||[];const opp=members.find(m=>m.player_id!==s.currentPlayer);$('opponentName').textContent=opp?'Opponent':'Waiting…';$('opponentReady').textContent=opp?(opp.ready?'READY':'NOT READY'):'Waiting for opponent';$('startMatchBtn').classList.toggle('hidden',!(state.isHost&&members.length===2&&members.every(m=>m.ready)));return}if(s.match.status==='active'){if(state.phase!=='game'){state.phase='game';show('lobby',false);show('game',true)}renderGame(s);return}if(s.match.status==='completed'){finish(s);return}}catch(e){setConnection(false)}finally{clearTimeout(state.poll);if(state.phase!=='result')state.poll=setTimeout(pollState,1200)}}
function renderGame(s){const q=s.question;if(!q)return;state.round=s.match.current_question_index;state.timeLeft=Math.max(0,Math.ceil((new Date(s.match.current_deadline).getTime()-Date.now())/1000));$('round').textContent=`${String(state.round+1).padStart(2,'0')} / 20`;$('difficulty').textContent=String(q.difficulty||'medium').replace('_',' ').toUpperCase();$('questionText').textContent=q.question_text;const my=s.scores?.find(x=>x.player_id===s.currentPlayer);const opp=s.scores?.find(x=>x.player_id!==s.currentPlayer);$('score').textContent=money(my?.money);$('opponentScore').textContent=money(opp?.money);$('opponentState').textContent=opp?.answered?'Answered':'Thinking…';if(state.answered||s.answers?.some(a=>a.player_id===s.currentPlayer)){state.answered=true;document.querySelectorAll('.option').forEach(b=>b.disabled=true)}else{state.answered=false;$('options').innerHTML=[q.option_a,q.option_b,q.option_c,q.option_d].map((x,i)=>`<button class="option" data-option="${String.fromCharCode(65+i)}"><b>${String.fromCharCode(65+i)}</b>${esc(x)}</button>`).join('');document.querySelectorAll('.option').forEach(b=>b.onclick=()=>submitAnswer(b.dataset.option))}if(s.reveal){$('reveal').classList.remove('hidden');$('reveal').textContent=`Correct answer: ${s.revealCorrectOption}`;if(s.revealCorrectOption)document.querySelectorAll('.option').forEach(b=>{if(b.dataset.option===s.revealCorrectOption)b.classList.add('correct')});clearInterval(state.timer);setTimeout(async()=>{const r=await backend.advanceMatch(state.matchId);if(r.status==='completed')await pollState();else await pollState()},900)}else{$('reveal').classList.add('hidden');startTimer()}}
function startTimer(){clearInterval(state.timer);state.timer=setInterval(()=>{state.timeLeft=Math.max(0,state.timeLeft-1);$('timer').textContent=state.timeLeft;if(state.timeLeft<=0){clearInterval(state.timer);pollState()}},1000)}
async function submitAnswer(opt){if(state.answered)return;state.answered=true;clearInterval(state.timer);document.querySelectorAll('.option').forEach(b=>b.disabled=true);try{const r=await backend.submitMatchAnswer(state.matchId,opt);if(r.correct)notice('Correct! Waiting for the other player…');else notice('Wrong answer. Waiting for the other player…','error');pollState()}catch(e){notice(e.message||'Answer rejected.','error');state.answered=false;document.querySelectorAll('.option').forEach(b=>b.disabled=false)}}
function finish(s){clearInterval(state.timer);state.phase='result';show('game',false);show('lobby',false);show('result',true);const mine=s.scores?.find(x=>x.player_id===s.currentPlayer);const opp=s.scores?.find(x=>x.player_id!==s.currentPlayer);const myMoney=Number(mine?.money||0),opMoney=Number(opp?.money||0);$('finalScore').textContent=money(myMoney);$('finalOpponent').textContent=money(opMoney);$('resultTitle').textContent=myMoney===opMoney?'MATCH TIED':myMoney>opMoney?'YOU WON':'OPPONENT WON';$('resultMessage').textContent=`${mine?.correct||0} correct answers for you versus ${opp?.correct||0} for your opponent.`}
async function rematch(){location.reload()}
function bind(){$('createRoom').onclick=createRoom;$('joinRoom').onclick=joinRoom;$('quickMatch').onclick=quickMatch;$('readyBtn').onclick=setReady;$('startMatchBtn').onclick=startMatch;$('leaveLobby').onclick=()=>{clearTimeout(state.poll);location.reload()};$('copyCode').onclick=()=>navigator.clipboard?.writeText(state.roomCode).then(()=>notice('Room code copied.'));$('rematch').onclick=rematch}
renderShell()
(async()=>{if(requireAuth()){try{const s=await backend.getSession();if(s){$('mpStatus').textContent='Signed in. Create a private room, join a room, or use Quick Match.'}}catch{}}})()
